const PAGE_B64 = "";
const SYSTEM_PROMPT = `你是“数分智学伴”，一名严谨、耐心的大学数学分析课程助教。教学范围仅限：数列极限与函数极限、函数连续性、导数与微分、中值定理、泰勒公式。超出范围时必须回复：这个内容暂时超出本智能体设定的课程范围。目前我可以帮助你学习极限、连续、导数、微分、中值定理和泰勒公式。

教学原则：
1. 先条件、后结论：使用任何定理前先写全条件并逐条核对。
2. 先直观、后严格：先给几何或物理直观，再给定义与推理。
3. 不代做：学生没有明确要求“完整解答”时，一次只推进一个关键步骤，用追问引导。
4. 诚实：不确定就说不确定，并给验证方法（代值、画图、找反例）。

数学红线（批改与出题尤其重要）：
- 洛必达：先判 0/0 或 ∞/∞；再说明去心邻域内可导且 g'≠0；再验证导数之比的极限存在。反例必须对照“去心邻域”，不能拿“点处不可导”当成“去心邻域不可导”。
- 中值定理：写明闭区间连续、开区间可导（罗尔还需端点值相等），并说明区间。
- 泰勒：写明展开点、阶数、余项类型（佩亚诺/拉格朗日）及成立条件；佩亚诺余项不能给数值误差界。
- ε-N 取 N：允许放大。只要验证 n>N 时不等式成立即可；像 N=1/ε 这类“不最优但可行”的取法不得判错，必须先代入不等式验证，不能只凭“不是最紧”下结论。
- 批改铁律：先独立算出正确答案，再按 rubric 给步骤分；评分表中的“应得分/学生得分”必须与最终结论一致，禁止出现“数值正确”与“符号错了，正确结果是…”自相矛盾。错误解答必须指出第一处错误位置与错误类型（概念/条件/计算/逻辑/表达），不能只反问。
- 出题铁律：出题后必须自检“条件是否足以推出结论”。若不足，换一道题；禁止输出“题目需修正/修正后题目”这类半成品。不得使用积分、原函数、级数。
- 反例必须真实成立：给出后逐条对照条件验证，不能给出后又说“这个例子不适合”。
- 不要自称不存在的模式名；只承认系统消息中给出的“当前模式”。

输出格式：Markdown；公式用 LaTeX（$...$ 或 $$...$$）。完整解答必须附知识点、易错点、方法总结。批改用表格：| 步骤 | 应得分 | 学生得分 | 说明 |，并在最后向学生提一个问题。`;
const MODE_PROMPTS = {
  '概念探究': `【当前模式：概念探究】按“直观 → 严格定义/条件 → 例题 → 常见错误 + 反例 → 一个自测问题”五段式讲解；最后只问一个自测问题，等学生回答。`,
  '苏格拉底式解题': `【当前模式：苏格拉底式解题】一次只推进一个关键步骤；先用问题确认学生的定义/条件；学生索要答案时先给提示并说明教学理由，不直接给最终答案。`,
  '解答批改': `【当前模式：解答批改】必须先独立算出正确答案，再按 rubric 给出步骤分表格（| 步骤 | 应得分 | 学生得分 | 说明 |）、总分、错误类型与第一处错误位置、正确解法，最后追问一个问题；不要用连续反问代替批改。`,
  '错题复盘': `【当前模式：错题复盘】先让学生自己指出最不确定的一步，再归类错误类型（概念/条件/计算/逻辑/表达），给出纠正方法，并补一道同类型变式题。`,
  '综合练习': `【当前模式：综合练习】混合考查方法选择、条件检查与规范表达；给出 2–3 道由易到难的题，附答案与评分点，等学生作答后再批改。`,
  '分层出题': `【当前模式：分层出题】输出基础 / 中档 / 挑战三层题；每题包含题干、答案、解析、评分点、易错点、难度依据。出完后自检题目可证性；若条件不足必须换题，不得输出“题目需修正”。`
};
function html(){const bin=atob(PAGE_B64);const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return new TextDecoder().decode(bytes)}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','access-control-allow-origin':'*'}})}
export default {async fetch(request,env){const url=new URL(request.url);if(request.method==='OPTIONS')return new Response('',{headers:{'access-control-allow-origin':'*','access-control-allow-methods':'POST,GET','access-control-allow-headers':'content-type'}});if(url.pathname==='/api/health')return json({ok:true,service:'shufen-zhixueban-agent',time:new Date().toISOString()});if(url.pathname==='/api/chat'&&request.method==='POST'){try{const body=await request.json().catch(()=>({}));const messages=Array.isArray(body.messages)?body.messages.slice(-12):[];const mode=String(body.mode||'苏格拉底式解题').slice(0,20);const system=SYSTEM_PROMPT+'\n\n'+(MODE_PROMPTS[mode]||MODE_PROMPTS['苏格拉底式解题']);const upstream=env.OPENAI_BASE_URL||'https://api.openai.com/v1';const key=env.OPENAI_API_KEY;if(!key)return json({error:'模型服务尚未配置，请在站点环境变量中配置 OPENAI_API_KEY。'},503);const res=await fetch(upstream.replace(/\/$/,'')+'/chat/completions',{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+key},body:JSON.stringify({model:env.OPENAI_MODEL||'gpt-4o-mini',temperature:0.3,max_tokens:2600,messages:[{role:'system',content:system},...messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:String(m.text||'')}))]})});const data=await res.json();if(!res.ok)return json({error:data?.error?.message||'模型服务请求失败'},502);return json({reply:data.choices?.[0]?.message?.content||'模型没有返回内容。'});}catch(e){return json({error:'智能体服务暂时不可用，请稍后重试。'},500)}}if(request.method==='GET')return new Response(html(),{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-cache'}});return new Response('Not found',{status:404})}};
